sys_security_acl.script:
answer = false;
var task = new GlideRecord('x_snc_discharge_0_discharge_task');
task.addQuery('discharge_case.patient', current.sys_id);
task.query();
while (task.next()) {
    if (gs.getUser().isMemberOf(task.assigned_group)) {
        answer = true;
        break;
    }
}
